import assert from 'node:assert/strict';
import {createGardenState,stepGarden,restoreGardenState,retryGarden} from '../../../../src/js/garden/GardenSimulation.js';
import {GARDEN_BEETLES,tickGardenBeetles,tickGardenBee,tickGardenWorm,sweptGardenContact} from '../../../../src/js/garden/GardenEncounters.js';
const fixture=()=>{const s=createGardenState();s.stage='RUNNING';for(const e of s.enemies){e.alive=false;e.hp=0;}return s;};
let s=fixture(),b=s.encounters.bees[0];
Object.assign(s.player,{x:b.x-200,y:590,onGround:true,support:'primeiros-bichinhos'});b.cooldown=0;tickGardenBee(b,s,.01);assert.equal(b.phase,'prepare');const y=b.y;
tickGardenBee(b,s,.4);assert.equal(b.phase,'prepare');assert.equal(b.y,y,'Aviso não inicia o rasante prematuramente');tickGardenBee(b,s,.11);assert.equal(b.phase,'dive');
for(let i=0;i<300;i++){s.time+=1/120;tickGardenBee(b,s,1/120);}assert.equal(b.phase,'patrol','Retorna à patrulha');assert.ok(b.cooldown>0,'Intervalo antes de novo ataque');
s=fixture();b=s.encounters.bees[0];Object.assign(b,{phase:'dive',fromX:b.x,targetX:b.x,fromY:578,targetY:578,y:578,age:.7});Object.assign(s.player,{x:b.x,y:541,vy:500,onGround:false,support:null});stepGarden(s,{},.03);assert.equal(b.alive,false,'Pisão derrota a abelha');assert.equal(s.hp,3,'Pisão sem dano');assert.ok(s.player.vy<0,'Reação do pisão preservada');
s=fixture();b=s.encounters.bees[0];Object.assign(b,{phase:'dive',fromX:b.x,targetX:b.x,fromY:550,targetY:550,y:550,age:.7});Object.assign(s.player,{x:b.x,y:580,vy:0,onGround:false,support:null});stepGarden(s,{},.02);assert.equal(s.hp,2,'Contato lateral tira um ponto');assert.equal(b.alive,true);stepGarden(s,{},.02);assert.equal(s.hp,2,'Proteção impede dano duplicado');
assert.equal(sweptGardenContact({x:0,y:580},{x:200,y:580},{x:100,y:550},{x:100,y:550,w:62,h:32}),true,'Varredura detecta cruzamento');
const round=restoreGardenState(structuredClone(s));assert.deepEqual(round.encounters,s.encounters,'Rasante restaurado');
const legacy=structuredClone(createGardenState());legacy.version=6;delete legacy.encounters;legacy.stage='RUNNING';const migrated=restoreGardenState(legacy);assert.equal(migrated.version,7);assert.equal(migrated.enemies.length,legacy.enemies.length);assert.equal(migrated.player.x,legacy.player.x,'Migração mantém posição no mesmo mapa');
assert.throws(()=>restoreGardenState({...s,encounters:{bees:[]}}));
s=fixture();let w=s.encounters.worms[0];s.player.x=w.x-400;tickGardenWorm(w,s,.1);assert.equal(w.exposure,0);s.player.x=w.x-200;tickGardenWorm(w,s,.22);assert.equal(w.exposure,1);assert.ok(w.h>0);s.player.x=w.x+400;tickGardenWorm(w,s,.22);assert.equal(w.exposure,0,'Recolhe longe');
s=fixture();w=s.encounters.worms[0];Object.assign(w,{exposure:1,emerging:true,h:63});Object.assign(s.player,{x:w.x,y:w.y-65,vy:500,onGround:false,support:null});const events=stepGarden(s,{},.04);assert.equal(s.hp,2,'Topo da minhoca tira um ponto');assert.equal(w.alive,true,'Pisão não derrota a minhoca');assert.ok(!events.some(e=>e.type==='stomp'));assert.equal(restoreGardenState(structuredClone(s)).encounters.worms[0].exposure,w.exposure);
s=fixture();const trigger=GARDEN_BEETLES[0];Object.assign(s.player,{x:trigger.x+1,y:590,onGround:true,support:'trecho-0-margem'});const control=structuredClone(s);control.encounters.consumed=GARDEN_BEETLES.map(b=>b.id);
for(let i=0;i<10;i++){stepGarden(s,{x:-1,jump:false},1/120);stepGarden(control,{x:1,jump:false},1/120);}assert.ok(s.encounters.panic);assert.equal(s.player.x,control.player.x,'Medo mantém velocidade física normal');assert.equal(s.player.vx,control.player.vx);assert.equal(s.hp,control.hp,'Besouro não tira vida');
stepGarden(s,{x:-1,jump:true},1/120);assert.ok(s.player.vy<0,'Pulo continua manual durante pânico');const savedPanic=restoreGardenState(structuredClone(s));assert.deepEqual(savedPanic.encounters.panic,s.encounters.panic,'Pânico no ar restaurado');
let elapsed=s.encounters.panic.elapsed;for(let i=0;s.encounters.panic&&i<1000;i++){tickGardenBeetles(s,1/120,[]);elapsed+=1/120;}assert.ok(Math.abs(elapsed-6)<.009,'Dura seis segundos ativos');assert.equal(s.encounters.panic,null);assert.ok(s.encounters.exit,'Besouro vai embora');
s.stage='GAME_OVER';s.checkpoint=45088+120;retryGarden(s);assert.ok(!s.encounters.consumed.includes('besouro-nuvens-finais'),'Nova tentativa rearma encontro final');
for(const difficulty of ['NORMAL','EASY']){s=fixture();s.difficulty=difficulty;Object.assign(s.player,{x:trigger.x+1,onGround:true});tickGardenBeetles(s,.01,[]);assert.equal(s.encounters.panic.remaining,6,'Mesma duração nas dificuldades');}
assert.equal(GARDEN_BEETLES.length,3);assert.ok(GARDEN_BEETLES[2].x>45088);
console.log('APROVADO: abelha/minhoca, 3 besouros inofensivos, seis segundos, velocidade normal, pulo manual, save no ar e retry.');
